import React, { useState } from 'react';
import { Line } from 'react-chartjs-2';
import { Chart as ChartJS, CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend } from 'chart.js';
import ManageTeachers from './ManageTeachers'; // මේක Import කරන්න අමතක කරන්න එපා

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend);

export default function LmsDashboard({ handleLogout }) {
  const [currentSubPage, setCurrentSubPage] = useState('Overview');

  const menuItems = [
    { name: 'Overview', icon: '📊' },
    { name: 'Students', icon: '👨‍🎓' },
    { name: 'Teachers & Classes', icon: '🏫' },
    { name: 'Manage Teachers', icon: '👩‍🏫' }, // අලුතින් එකතු කළා
    { name: 'Reports', icon: '📋' },
    { name: 'Settings', icon: '⚙️' }
  ];

  const stats = { totalStudents: '1,250', totalTeachers: '45', activeClasses: '120', inactiveStudents: '25' };

  const growthData = {
    labels: ['Jan', 'Feb', 'Mar', 'Apr', 'May'],
    datasets: [{
      label: 'Enrollment Growth',
      data: [10, 32, 25, 48, 80],
      borderColor: '#15803d',
      backgroundColor: 'rgba(21, 128, 61, 0.1)',
      tension: 0.4,
      fill: true
    }]
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', minHeight: '100vh', width: '100vw', fontFamily: 'sans-serif', backgroundColor: '#f8fafc' }}>
      
      {/* Header */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '18px 40px', borderBottom: '1px solid #e2e8f0', backgroundColor: '#ffffff', width: '100%', boxSizing: 'border-box', zIndex: 10 }}>
        <span style={{ fontWeight: '700', color: '#1e293b', fontSize: '15px' }}>Welcome, admin 👋</span>
        <button onClick={handleLogout} style={{ backgroundColor: '#dc2626', color: '#ffffff', border: 'none', padding: '8px 16px', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold', fontSize: '13px' }}>Logout</button>
      </div>

      <div style={{ display: 'flex', flex: 1, width: '100%' }}>
        
        {/* Sidebar */}
        <div style={{ width: '260px', backgroundColor: '#15803d', color: '#ffffff', display: 'flex', flexDirection: 'column', padding: '25px 0', boxSizing: 'border-box', flexShrink: 0 }}>
          <div style={{ padding: '0 25px 20px 25px', borderBottom: '1px solid rgba(255,255,255,0.1)' }}>
            <h2 style={{ fontSize: '20px', fontWeight: 'bold', margin: 0 }}>Admin Panel</h2>
          </div>
          <nav style={{ marginTop: '25px', display: 'flex', flexDirection: 'column', gap: '8px', padding: '0 15px' }}>
            {menuItems.map((item) => {
              const isActive = currentSubPage === item.name;
              return (
                <button key={item.name} onClick={() => setCurrentSubPage(item.name)} style={{ display: 'flex', alignItems: 'center', gap: '14px', width: '100%', padding: '12px 15px', backgroundColor: isActive ? 'rgba(0, 0, 0, 0.2)' : 'transparent', color: '#ffffff', border: 'none', borderRadius: '8px', cursor: 'pointer', fontSize: '14px', fontWeight: isActive ? '600' : '500', textAlign: 'left' }}>
                  <span>{item.icon}</span><span>{item.name}</span>
                </button>
              );
            })}
          </nav>
        </div>

        {/* Content Area */}
        <div style={{ flex: 1, padding: '40px', display: 'flex', flexDirection: 'column', gap: '30px', backgroundColor: '#f8fafc' }}>
          
          {currentSubPage === 'Overview' && (
            <>
              {/* Stats Cards */}
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '25px' }}>
                {[ { t: 'Total Students', v: stats.totalStudents, i: '👨‍🎓' }, { t: 'Total Teachers', v: stats.totalTeachers, i: '👩‍🏫' }, { t: 'Active Classes', v: stats.activeClasses, i: '🏫' }, { t: 'Inactive Students', v: stats.inactiveStudents, i: '⚠️' } ].map((card, i) => (
                  <div key={i} style={{ background: '#ffffff', padding: '25px', borderRadius: '16px', border: '1px solid #e2e8f0', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <div><p style={{ color: '#64748b', fontSize: '13px', margin: '0 0 6px 0' }}>{card.t}</p><h2 style={{ margin: 0, color: '#1e293b', fontSize: '28px', fontWeight: '700' }}>{card.v}</h2></div>
                    <span style={{ fontSize: '28px' }}>{card.i}</span>
                  </div>
                ))}
              </div>

              {/* Chart & Table */}
              <div style={{ display: 'grid', gridTemplateColumns: '2.5fr 1fr', gap: '25px' }}>
                <div style={{ background: '#ffffff', padding: '25px', borderRadius: '16px', border: '1px solid #e2e8f0' }}>
                  <h3 style={{ margin: '0 0 20px 0', fontSize: '15px', color: '#1e293b' }}>Enrollment Growth</h3>
                  <div style={{ height: '220px' }}><Line data={growthData} options={{ responsive: true, maintainAspectRatio: false }} /></div>
                </div>
                <div style={{ background: '#ffffff', padding: '25px', borderRadius: '16px', border: '1px solid #e2e8f0' }}>
                  <h3 style={{ margin: '0 0 20px 0', fontSize: '15px', fontWeight: '600', color: '#1e293b' }}>Student Status</h3>
                  <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                    {[{ name: 'Ruwan', status: 'Active' }, { name: 'Sama', status: 'Inactive' }].map((s, i) => (
                      <div key={i} style={{ display: 'flex', justifyContent: 'space-between', borderBottom: '1px solid #f1f5f9', padding: '8px 0' }}>
                        <span>{s.name}</span><span>{s.status}</span>
                      </div>
                    ))}
                  </div>
                </div>
              </div>

              {/* Buttons */}
              <div style={{ display: 'flex', gap: '15px', marginTop: '10px' }}>
                <button style={{ backgroundColor: '#15803d', color: 'white', border: 'none', padding: '12px 24px', borderRadius: '8px', cursor: 'pointer' }}>Manage Students</button>
                <button onClick={() => setCurrentSubPage('Manage Teachers')} style={{ backgroundColor: '#ffffff', color: '#475569', border: '1px solid #cbd5e1', padding: '12px 24px', borderRadius: '8px', cursor: 'pointer' }}>Manage Teachers</button>
              </div>
            </>
          )}

          {/* Subpages logic */}
          {currentSubPage === 'Manage Teachers' && <ManageTeachers />}
          {currentSubPage === 'Students' && <div><h2>👨‍🎓 Student Management Section</h2></div>}
          {currentSubPage === 'Teachers & Classes' && <div><h2>🏫 Teachers & Classes Section</h2></div>}
          {currentSubPage === 'Reports' && <div><h2>📋 Academic Reports Section</h2></div>}
          {currentSubPage === 'Settings' && <div><h2>⚙️ System Settings Section</h2></div>}
        </div>
      </div>
    </div>
  );
}
